// à mão: ?horas=N (até 72) para buscar mais para trás; padrão: 3 h
let q = {}; try { q = $('Rodar agora').first().json.query || {}; } catch (e) {}
const horas = Math.min(72, Math.max(1, Number(q.horas) || 3)), ate = Math.floor(Date.now() / 1000);
return [{ json: { horas, de: ate - horas * 3600, ate } }];

// O que o robô do n8n manda direto pela API (22/11/2026) chega ao recebedor só como status "enviada", sem o texto (linha
// "sem texto", aparelho kommo). Aqui ganha uma descrição sem dado de paciente:
//   - confirmação da véspera: pelo id da mensagem guardado em BMH_confirmacoes;
//   - recado depois do "Confirmo": o paciente tocou "Confirmo" até 5 min antes, do mesmo telefone em código;
//   - NPS: o paciente tocou "Está ótima" ou "Está boa" (link do Google) ou "Podia ser melhor" até 5 min antes.
const conf = $('Confirmações (tabela)').all().map((i) => i.json).filter((r) => r && r.chave);
const porWamid = {}; for (const r of conf) if (r.wamid) porWamid[r.wamid] = r;
const linhas = $('Mensagens (tabela)').all().map((i) => i.json).filter((r) => r && r.chave);
const doPaciente = {}; for (const r of linhas) if (r.direcao === 'paciente' && r.tipo === 'botão') (doPaciente[r.telefone_hash] ||= []).push(r);
const { de } = $('Janela').first().json, desde = (de - 3 * 86400) * 1000;   // olha 3 dias para trás
const tipoDe = (h) => conf.filter((r) => r.telefone_hash === h && r.resposta === 'confirmou').sort((a, b) => String(b.dia).localeCompare(String(a.dia)))[0]?.tipo;
const out = [];
for (const r of linhas) {
  if (r.aparelho !== 'kommo' || r.texto || Date.parse(r.momento) < desde) continue;
  const c = porWamid[r.chave], [, m, d] = String(c?.dia || '').split('-');
  let texto = c ? `[robô] confirmação da véspera: ${c.tipo || 'sessão'} de ${d}/${m} às ${c.hora}, BMH ${c.unidade}` : '';
  if (!texto) {
    const t = Date.parse(r.momento), b = (doPaciente[r.telefone_hash] || []).filter((x) => t - Date.parse(x.momento) >= 0 && t - Date.parse(x.momento) <= 300000).sort((a, b2) => Date.parse(b2.momento) - Date.parse(a.momento))[0];
    const bt = String(b?.texto || '').trim().toLowerCase();
    if (bt === 'confirmo') texto = tipoDe(r.telefone_hash) === 'avaliação' ? '[robô] recado da confirmação: mapa da unidade' : '[robô] recado da confirmação: chegar 20 a 30 min antes e mapa da unidade';
    else if (bt === 'está ótima' || bt === 'está boa') texto = '[robô] NPS: agradecimento com o link de avaliação do Google';
    else if (bt === 'podia ser melhor') texto = '[robô] NPS: resposta à nota baixa';
  }
  if (!texto) continue;
  const { id, createdAt, updatedAt, ...linha } = r;
  out.push({ json: { ...linha, tipo: 'texto', texto } });
}
return out;

// 250 eventos por página; uma página a cada 6 h de janela (página vazia volta sem corpo)
const { horas, de, ate } = $('Janela').first().json;
return Array.from({ length: Math.ceil(horas / 6) }, (_, k) => ({ json: { page: k + 1, de, ate } }));

const corpo = (j) => { const t = j && typeof j.data === 'string' ? j.data : j; if (!t) return {}; if (typeof t === 'object') return t; try { return JSON.parse(t); } catch (e) { return {}; } };
const ids = new Set(); for (const p of $input.all()) for (const e of (corpo(p.json)._embedded?.events || [])) for (const v of e.value_after || []) if (v.message?.talk_id) ids.add(v.message.talk_id);
return [...ids].map((talk_id) => ({ json: { talk_id } }));

const corpo = (j) => { const t = j && typeof j.data === 'string' ? j.data : j; if (!t) return {}; if (typeof t === 'object') return t; try { return JSON.parse(t); } catch (e) { return {}; } };
const ids = [...new Set($('Conversa (Kommo)').all().map((p) => corpo(p.json).contact_id).filter(Boolean))], out = [];
for (let i = 0; i < ids.length; i += 50) out.push({ json: { q: ids.slice(i, i + 50).map((id) => 'filter[id][]=' + id).join('&') } });
return out;

// Texto do que saiu pelo Kommo (22/11/2026, pedido do Jorge: "pode buscar o texto das mensagens do Kommo"). O recebedor oficial
// da Meta não recebe o que sai pelo Kommo (salesbot e recepção): conferido em 22/11/2026, 162 mensagens do Kommo em 24 h e
// nenhuma linha delas em BMH_whatsapp_meta (as linhas "sem texto" eram do robô do n8n). Aqui: eventos outgoing_chat_message do
// Kommo → mensagem da conversa (texto) → telefone do contato em código → linha nova em BMH_whatsapp_meta (chave "kommo:<id>"),
// direção equipe, aparelho kommo, texto mascarado como no recebedor. Se já existir linha sem texto do mesmo telefone até 3 min
// de diferença, preenche essa em vez de criar outra.
// SHA-256 em JavaScript puro (22/10/2026): o nó de código do n8n não garante o módulo crypto. Injetado no código dos nós pelo
// montar.js no lugar de /*__SHA256__*/. Conferido contra o crypto do Node em whatsapp/testa-monta-meta.js.
const sha256 = (s) => { const K = [0x428a2f98,0x71374491,0xb5c0fbcf,0xe9b5dba5,0x3956c25b,0x59f111f1,0x923f82a4,0xab1c5ed5,0xd807aa98,0x12835b01,0x243185be,0x550c7dc3,0x72be5d74,0x80deb1fe,0x9bdc06a7,0xc19bf174,0xe49b69c1,0xefbe4786,0x0fc19dc6,0x240ca1cc,0x2de92c6f,0x4a7484aa,0x5cb0a9dc,0x76f988da,0x983e5152,0xa831c66d,0xb00327c8,0xbf597fc7,0xc6e00bf3,0xd5a79147,0x06ca6351,0x14292967,0x27b70a85,0x2e1b2138,0x4d2c6dfc,0x53380d13,0x650a7354,0x766a0abb,0x81c2c92e,0x92722c85,0xa2bfe8a1,0xa81a664b,0xc24b8b70,0xc76c51a3,0xd192e819,0xd6990624,0xf40e3585,0x106aa070,0x19a4c116,0x1e376c08,0x2748774c,0x34b0bcb5,0x391c0cb3,0x4ed8aa4a,0x5b9cca4f,0x682e6ff3,0x748f82ee,0x78a5636f,0x84c87814,0x8cc70208,0x90befffa,0xa4506ceb,0xbef9a3f7,0xc67178f2];
  const b = Array.from(unescape(encodeURIComponent(s)), (c) => c.charCodeAt(0)), l = b.length * 8; b.push(0x80); while (b.length % 64 !== 56) b.push(0);
  for (let i = 7; i >= 0; i--) b.push(i > 3 ? 0 : (l >>> (i * 8)) & 0xff);
  let H = [0x6a09e667,0xbb67ae85,0x3c6ef372,0xa54ff53a,0x510e527f,0x9b05688c,0x1f83d9ab,0x5be0cd19]; const r = (x, n) => (x >>> n) | (x << (32 - n));
  for (let o = 0; o < b.length; o += 64) { const w = []; for (let i = 0; i < 64; i++) w[i] = i < 16 ? (b[o + 4 * i] << 24) | (b[o + 4 * i + 1] << 16) | (b[o + 4 * i + 2] << 8) | b[o + 4 * i + 3] : (((r(w[i - 2], 17) ^ r(w[i - 2], 19) ^ (w[i - 2] >>> 10)) + w[i - 7] + (r(w[i - 15], 7) ^ r(w[i - 15], 18) ^ (w[i - 15] >>> 3)) + w[i - 16]) | 0);
    let [a, bb, c, d, e, f, g, h] = H;
    for (let i = 0; i < 64; i++) { const t1 = (h + (r(e, 6) ^ r(e, 11) ^ r(e, 25)) + ((e & f) ^ (~e & g)) + K[i] + w[i]) | 0, t2 = ((r(a, 2) ^ r(a, 13) ^ r(a, 22)) + ((a & bb) ^ (a & c) ^ (bb & c))) | 0; h = g; g = f; f = e; e = (d + t1) | 0; d = c; c = bb; bb = a; a = (t1 + t2) | 0; }
    H = H.map((v, i) => (v + [a, bb, c, d, e, f, g, h][i]) | 0); }
  return H.map((v) => (v >>> 0).toString(16).padStart(8, '0')).join(''); };

const corpo = (j) => { const t = j && typeof j.data === 'string' ? j.data : j; if (!t) return {}; if (typeof t === 'object') return t; try { return JSON.parse(t); } catch (e) { return {}; } };
const mascara = (s) => String(s || '')
  .replace(/\b\d{3}\.?\d{3}\.?\d{3}-?\d{2}\b/g, '[cpf]')
  .replace(/[\w.+-]+@[\w-]+\.[\w.-]+/g, '[e-mail]')
  .replace(/(?:\+?55\s?)?\(?\d{2}\)?\s?9?\d{4}[-\s]?\d{4}\b/g, '[telefone]');
const { de, ate } = $('Janela').first().json;
// ids das mensagens que o Kommo mandou na janela, por conversa
const quer = new Set(); for (const p of $('Eventos (Kommo)').all()) for (const e of (corpo(p.json)._embedded?.events || []))
  for (const v of e.value_after || []) if (v.message?.id) quer.add(v.message.id);
// conversa → contato
const conversas = $('Conversas a ler').all().map((i) => i.json), contatoDa = {};
$('Conversa (Kommo)').all().forEach((p, k) => { const t = corpo(p.json); if (t.contact_id) contatoDa[conversas[k]?.talk_id] = t.contact_id; });
// contato → telefones em código (com e sem o 9, porque o número que a Meta usa às vezes vem sem o 9)
const hashes = {};
for (const p of $('Contatos (Kommo)').all()) for (const c of (corpo(p.json)._embedded?.contacts || [])) {
  const hs = new Set();
  for (const f of (c.custom_fields_values || []).filter((f) => f.field_code === 'PHONE')) for (const v of f.values || []) {
    let d = String(v.value || '').replace(/\D/g, ''); if (!d) continue; if (!d.startsWith('55') || d.length < 12) d = '55' + d;
    const n = d.slice(2); if (n.length === 11) { hs.add(sha256('55' + n)); hs.add(sha256('55' + n.slice(0, 2) + n.slice(3))); }
    else if (n.length === 10) { hs.add(sha256('55' + n)); hs.add(sha256('55' + n.slice(0, 2) + '9' + n.slice(2))); } }
  hashes[c.id] = hs; }
// mensagens do Kommo com texto
const enviadas = [];
$('Mensagens da conversa').all().forEach((p, k) => { const talk = conversas[k]?.talk_id, hs = hashes[contatoDa[talk]];
  if (!hs || !hs.size) return;
  for (const m of (corpo(p.json)._embedded?.messages || [])) if (m.type === 'outgoing' && quer.has(m.id))
    enviadas.push({ id: m.id, hs, hs_lista: [...hs], quando: Number(m.created_at) * 1000, texto: mascara(m.text) || '[' + (m.message_type || 'mensagem') + ']', autor: m.author?.type || '' }); });
// linhas já gravadas do mesmo telefone (para não repetir e para preencher a que estiver sem texto)
const linhas = $('Mensagens (tabela)').all().map((i) => i.json).filter((r) => r && r.chave);
const chaves = new Set(linhas.map((r) => r.chave)), conhecidos = new Set(linhas.map((r) => r.telefone_hash));
const dataSP = (ms) => new Date(ms).toLocaleDateString('sv-SE', { timeZone: 'America/Sao_Paulo' });
const usadas = new Set(), out = [];
for (const m of enviadas.sort((a, b) => a.quando - b.quando)) {
  if (chaves.has('kommo:' + m.id)) continue;   // já gravada numa rodada anterior
  const perto = linhas.filter((r) => r.aparelho === 'kommo' && m.hs.has(r.telefone_hash) && Math.abs(Date.parse(r.momento) - m.quando) <= 180000);
  if (perto.some((r) => String(r.texto || '').startsWith('[Kommo'))) continue;   // preenchida numa rodada anterior
  const texto = (m.autor === 'bot' ? '[Kommo · robô] ' : '[Kommo] ') + m.texto;
  const vazia = perto.filter((r) => !r.texto && !usadas.has(r.chave)).sort((a, b) => Math.abs(Date.parse(a.momento) - m.quando) - Math.abs(Date.parse(b.momento) - m.quando))[0];
  if (vazia) { usadas.add(vazia.chave); const { id, createdAt, updatedAt, ...r } = vazia; out.push({ json: { ...r, tipo: 'texto', texto } }); continue; }
  const hash = m.hs_lista.find((h) => conhecidos.has(h)) || m.hs_lista[0], apagar = new Date(m.quando); apagar.setMonth(apagar.getMonth() + 1);
  out.push({ json: { chave: 'kommo:' + m.id, momento: new Date(m.quando).toISOString(), dia: dataSP(m.quando), telefone_hash: hash, direcao: 'equipe', aparelho: 'kommo',
    tipo: 'texto', texto, respondendo: '', apagar_em: apagar.toISOString().slice(0, 10), origem: '', anuncio_id: '', ctwa_clid: '', referral_tipo: '' } });
}
return out;

// só contagens (é o que o "Rodar agora" devolve)
const n = (k) => { try { return $(k).all().length; } catch (e) { return 0; } };
return [{ json: { horas: $('Janela').first().json.horas, conversas: n('Conversas a ler'), texto_do_kommo: n('Casa as mensagens'), texto_do_robo: n('Texto do robô') } }];
